css:
.aha-header{
  container:aha-header / inline-size;
  font-family:var(--aha-font-product);
  color:var(--aha-text-default);
  background:var(--aha-white);
  position:relative;
}
.aha-header *{box-sizing:border-box}
:where(.aha-header) a{color:inherit;text-decoration:none}
.aha-header button{font-family:inherit}
.aha-header__join{
  display:flex;align-items:center;justify-content:center;flex-wrap:wrap;
  gap:var(--aha-space-12);
  min-height:var(--aha-space-56);
  padding:var(--aha-space-8) var(--aha-space-24);
  background:var(--aha-bg-dark);
  color:var(--aha-text-inverse);
}
.aha-header__join-label{font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold)}
.aha-header__join-form{
  display:flex;align-items:center;gap:var(--aha-space-8);
  padding:var(--aha-space-4) var(--aha-space-4) var(--aha-space-4) var(--aha-space-16);
  background:var(--aha-bg-dark-raised);
  border-radius:var(--aha-radius-default);
}
.aha-header__join-url{font-size:var(--aha-size-sm);color:var(--aha-white-a70)}
.aha-header__join-input{
  width:var(--aha-space-100);
  height:var(--aha-control-height-button-sm);
  border:0;background:transparent;
  font-family:inherit;font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-inverse);
  text-transform:uppercase;
}
.aha-header__join-input::placeholder{color:var(--aha-white-a70)}
.aha-header__join-input:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);border-radius:var(--aha-radius-xs)}
.aha-header__join-button{
  height:var(--aha-control-height-button-sm);
  padding:0 var(--aha-space-16);
  border:0;border-radius:var(--aha-radius-default);
  background:var(--aha-button-primary-bg);color:var(--aha-button-primary-text);
  font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);cursor:pointer;
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-header__join-button:hover{background:var(--aha-button-primary-bg-hover)}
.aha-header__join-button:active{background:var(--aha-button-primary-bg-press)}
.aha-header__join-button:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-header__nav{
  position:relative;
  display:flex;align-items:center;gap:var(--aha-space-32);
  min-height:var(--aha-space-80);
  padding:0 var(--aha-space-32);
  border-bottom:1px solid var(--aha-border-default);
  background:var(--aha-white);
}
.aha-header__brand{display:inline-flex;border-radius:var(--aha-radius-xs)}
.aha-header__brand:focus-visible,.aha-header__toggle:focus-visible,.aha-header__link:focus-visible,.aha-header__entry:focus-visible,.aha-header__button:focus-visible{
  outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);
}
.aha-header__toggle{
  display:none;margin-inline-start:auto;
  width:var(--aha-control-height-button-lg);height:var(--aha-control-height-button-lg);
  align-items:center;justify-content:center;
  border:0;border-radius:var(--aha-radius-default);background:transparent;
  color:var(--aha-text-default);cursor:pointer;
}
.aha-header__toggle:hover{background:var(--aha-button-ghost-bg-hover)}
.aha-header__toggle:active{background:var(--aha-button-ghost-bg-press)}
.aha-header__toggle-close{display:none}
.aha-header[data-menu="open"] .aha-header__toggle-open{display:none}
.aha-header[data-menu="open"] .aha-header__toggle-close{display:inline-flex}
.aha-header__menu{display:flex;flex:1;align-items:center;justify-content:space-between;gap:var(--aha-space-24)}
.aha-header__links{display:flex;align-items:center;gap:var(--aha-space-4)}
.aha-header__actions{display:flex;align-items:center;gap:var(--aha-space-12)}
.aha-header__item{position:relative}
.aha-header__link{
  display:inline-flex;align-items:center;gap:var(--aha-space-4);
  height:var(--aha-control-height-button-lg);
  padding:0 var(--aha-space-12);
  border:0;border-radius:var(--aha-radius-default);background:transparent;
  font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-default);cursor:pointer;
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-header__link:hover,.aha-header__item.is-open>.aha-header__link{background:var(--aha-button-ghost-bg-hover);color:var(--aha-text-link-hover)}
.aha-header__link:active{background:var(--aha-button-ghost-bg-press)}
.aha-header__link aha-icon{transition:transform var(--aha-motion-mid) var(--aha-ease-in-out)}
.aha-header__item.is-open>.aha-header__link aha-icon:last-child{transform:rotate(180deg)}
.aha-header__language{padding:0 var(--aha-space-12)}
.aha-header__panel{
  display:none;
  position:absolute;top:100%;inset-inline-start:0;z-index:2;
  min-width:15rem;
  margin-top:var(--aha-space-8);
  padding:var(--aha-space-16);
  background:var(--aha-bg-elevated);
  border:1px solid var(--aha-border-default);
  border-radius:var(--aha-radius-lg);
}
.aha-header__panel::before{content:"";position:absolute;inset-inline:0;top:calc(-1 * var(--aha-space-8) - 1px);height:calc(var(--aha-space-8) + 1px)}
.aha-header__panel--wide{gap:var(--aha-space-32);min-width:max-content}
.aha-header__panel--end{inset-inline-start:auto;inset-inline-end:0;min-width:11rem}
.aha-header__item.is-open>.aha-header__panel{display:block}
.aha-header__item.is-open>.aha-header__panel--wide{display:flex}
@media (hover:hover){
  .aha-header__item:hover>.aha-header__panel{display:block}
  .aha-header__item:hover>.aha-header__panel--wide{display:flex}
}
.aha-header__col{display:flex;flex-direction:column;gap:var(--aha-space-2);min-width:13rem}
.aha-header__col--slides{min-width:18rem}
.aha-header__grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-2)}
.aha-header__label{
  margin:var(--aha-space-8) var(--aha-space-12) var(--aha-space-4);
  font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-secondary);
}
.aha-header__label:first-child{margin-top:0}
.aha-header__label:not(:first-child){margin-top:var(--aha-space-16)}
.aha-header__entry{
  display:flex;align-items:center;gap:var(--aha-space-12);
  min-height:var(--aha-control-height-button-md);
  padding:var(--aha-space-6) var(--aha-space-12);
  border-radius:var(--aha-radius-default);
  font-size:var(--aha-size-default);font-weight:var(--aha-weight-regular);
  color:var(--aha-text-default);
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-header__entry:hover{background:var(--aha-button-ghost-bg-hover);color:var(--aha-text-link-hover)}
.aha-header__entry:active{background:var(--aha-button-ghost-bg-press)}
.aha-header__entry[aria-current="true"]{font-weight:var(--aha-weight-semibold);background:var(--aha-bg-accent)}
.aha-header__entry--more{margin-top:var(--aha-space-8);font-weight:var(--aha-weight-semibold);color:var(--aha-text-link-hover)}
.aha-header__button{
  display:inline-flex;align-items:center;justify-content:center;
  height:var(--aha-control-height-button-lg);
  padding:0 var(--aha-space-20);
  border:1px solid var(--aha-button-default-border);
  border-radius:var(--aha-radius-pill);
  background:var(--aha-button-default-bg);color:var(--aha-button-default-text);
  font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);
  white-space:nowrap;
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-header__button:hover{background:var(--aha-button-default-bg-hover);border-color:var(--aha-button-default-border-hover);color:var(--aha-button-default-text-hover)}
.aha-header__button:active{border-color:var(--aha-button-default-border-press)}
.aha-header__button--primary{background:var(--aha-button-primary-bg);border-color:transparent;color:var(--aha-button-primary-text)}
.aha-header__button--primary:hover{background:var(--aha-button-primary-bg-hover);border-color:transparent;color:var(--aha-button-primary-text)}
.aha-header__button--primary:active{background:var(--aha-button-primary-bg-press);border-color:transparent}
@container aha-header (max-width:991px){
  .aha-header__nav{flex-wrap:wrap;gap:var(--aha-space-16);padding:var(--aha-space-12) var(--aha-space-24);min-height:var(--aha-space-68)}
  .aha-header__toggle{display:inline-flex}
  .aha-header__menu{display:none;flex-basis:100%;flex-direction:column;align-items:stretch;gap:var(--aha-space-16);padding:var(--aha-space-8) 0 var(--aha-space-16)}
  .aha-header[data-menu="open"] .aha-header__menu{display:flex}
  .aha-header__links{flex-direction:column;align-items:stretch;gap:var(--aha-space-2)}
  .aha-header__link{width:100%;justify-content:space-between;height:var(--aha-control-height-button-xl)}
  .aha-header__panel::before{display:none}
  .aha-header__panel,.aha-header__panel--end{position:static;margin:0;border:0;padding:var(--aha-space-4) 0 var(--aha-space-8) var(--aha-space-12);min-width:0;background:transparent}
  .aha-header__panel--wide{flex-direction:column;gap:var(--aha-space-8);min-width:0}
  .aha-header__col,.aha-header__col--slides{min-width:0}
  .aha-header__actions{flex-direction:column;align-items:stretch}
  .aha-header__actions .aha-header__item--language .aha-header__link{justify-content:flex-start}
  .aha-header__button{width:100%;height:var(--aha-control-height-button-xl)}
}
@container aha-header (max-width:600px){
  .aha-header__join{padding:var(--aha-space-12) var(--aha-space-16);gap:var(--aha-space-8)}
  .aha-header__join-form{width:100%}
  .aha-header__join-input{flex:1;width:auto}
  .aha-header__nav{padding:var(--aha-space-8) var(--aha-space-16)}
  .aha-header__grid{grid-template-columns:minmax(0,1fr)}
}
@media (prefers-reduced-motion:reduce){
  .aha-header *{transition:none!important}
}
